// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = { name: 'Young Astronaut' };
async function build() {
  const root=createRoot('YoungAstronaut');
  const M=styleMaterials();
  M.panel.flatShading=false;
  M.visor.flatShading=false;
  const ball=(name,parent,position,scale,material,segments=12)=>createPart(name,sphereGeo(1,segments,8),material,{parent,position,scale});
  const soft=async(name,parent,position,size,material,r=.04)=>createPart(name,await roundedBoxGeo(...size,r,{style:'round',segments:2,smooth:true}),material,{parent,position});
  const panel=async(name,parent,position,size,material,r=.015)=>createPart(name,await roundedBoxGeo(...size,r,{style:'chamfer'}),material,{parent,position});
  const cyl=(name,parent,position,top,bottom,height,material,rotation=[0,0,0])=>createPart(name,cylinderGeo(top,bottom,height,12),material,{parent,position,rotation});
  const hips=createPivot('Hips',[0,.67,0],root);
  ball('PaddedHips',hips,[0,-.025,0],[.20,.18,.255],M.panel);
  const spine=createPivot('Spine',[0,.10,0],hips);
  await soft('SuitTorso',spine,[0,.16,0],[.39,.46,.51],M.panel,.09);
  await soft('WaistBelt',spine,[0,-.035,0],[.405,.066,.51],M.accent,.022);
  await panel('BeltBuckle',spine,[.216,-.035,0],[.037,.076,.09],M.panelGray,.009);
  await panel('LifeSupportFrame',spine,[-.255,.17,0],[.18,.43,.40],M.trim,.04);
  await panel('LifeSupportShell',spine,[-.326,.17,0],[.11,.39,.365],M.panelGray,.035);
  await panel('BackDisplayBezel',spine,[-.389,.29,0],[.025,.074,.235],M.trim,.008);
  await panel('BackDisplay',spine,[-.404,.29,0],[.012,.042,.185],M.glowCool,.004);
  await panel('BackAccessDoor',spine,[-.392,.11,0],[.03,.205,.23],M.trim,.012);
  await panel('BackAccessPanel',spine,[-.410,.11,0],[.015,.17,.193],M.panelGray,.006);
  await panel('BackStatus',spine,[-.421,.157,0],[.009,.019,.065],M.glowCool,.004);
  await panel('BackHandle',spine,[-.419,.232,0],[.027,.027,.14],M.panel,.007);
  await panel('ChestConsole',spine,[.208,.16,0],[.065,.31,.32],M.panel,.021);
  for(const s of [-1,1]) {
    await panel('UpperControl'+s,spine,[.252,.235,s*.084],[.04,.105,.105],M.panelGray,.012);
    await panel('UpperOrangeTab'+s,spine,[.257,.287,s*.084],[.043,.019,.09],M.accent,.005);
    await panel('LowerControl'+s,spine,[.251,.09,s*.093],[.042,.074,.071],M.accent,.008);
    await panel('LowerSwitch'+s,spine,[.277,.09,s*.093],[.017,.045,.024],M.panelGray,.004);
  }
  await panel('ChestSlot',spine,[.247,.047,0],[.014,.011,.068],M.panelGray,.003);
  const neck=createPivot('Neck',[0,.39,0],spine);
  cyl('PressureCollar',neck,[0,0,0],.19,.20,.075,M.trim);
  const head=createPivot('Head',[0,.17,0],neck);
  ball('HelmetShell',head,[-.025,0,0],[.305,.31,.325],M.panel,24);
  // Broad oval pressure visor overlays the forward shell and leaves an ivory rim.
  ball('VisorGasket',head,[.184,-.006,0],[.171,.255,.287],M.trim,24);
  ball('NavyVisor',head,[.202,-.002,0],[.164,.241,.273],M.visor,24);
  await panel('ChinLatch',head,[.251,-.257,0],[.069,.035,.108],M.accent,.01);
  for(const s of [-1,1]) {
    cyl('HelmetPuckBase'+s,head,[.008,0,s*.321],.091,.091,.055,M.panelGray,[90,0,0]);
    cyl('HelmetPuckRim'+s,head,[.008,0,s*.349],.08,.08,.036,M.panel,[90,0,0]);
    cyl('HelmetOrangePuck'+s,head,[.008,0,s*.373],.063,.063,.022,M.accent,[90,0,0]);
  }
  for(const side of [-1,1]) {
    const n=side===1?'Right':'Left';
    const shoulder=createPivot(n+'Shoulder',[0,.29,side*.285],spine);
    shoulder.rotation.x=-side*12*Math.PI/180;
    ball(n+'ShoulderSeal',shoulder,[0,-.015,0],[.126,.135,.12],M.panelGray);
    ball(n+'UpperSleeve',shoulder,[0,-.105,0],[.122,.164,.119],M.panel);
    const pad=await panel(n+'ShoulderPad',shoulder,[.045,-.047,side*.09],[.22,.155,.09],M.accent,.024);
    await panel(n+'ShoulderFrontPad',shoulder,[.112,-.052,side*.045],[.048,.135,.14],M.accent,.014);
    pad.rotation.x=-side*.20;
    const elbow=createPivot(n+'Elbow',[0,-.235,0],shoulder);
    ball(n+'ElbowSeal',elbow,[0,0,0],[.10,.065,.10],M.trim);
    cyl(n+'ElbowBand',elbow,[0,-.006,0],.112,.112,.055,M.accent);
    const forearm=await soft(n+'Forearm',elbow,[0,-.114,0],[.215,.24,.215],M.panel,.045);
    cyl(n+'Cuff',elbow,[0,-.207,0],.114,.114,.055,M.panel);
    const wrist=createPivot(n+'Wrist',[0,-.242,0],elbow);
    await soft(n+'GlovePalm',wrist,[.012,-.046,0],[.14,.135,.15],M.trim,.04);
    ball(n+'Thumb',wrist,[.075,-.026,-side*.043],[.036,.058,.035],M.trim);
    for(let f=0;f<3;f++)ball(n+'Finger'+f,wrist,[.021,-.103,(f-1)*.044],[.054,.032,.023],M.trim,8);
    const hip=createPivot(n+'Hip',[0,-.085,side*.142],hips);
    ball(n+'UpperLeg',hip,[0,-.091,0],[.132,.18,.13],M.panel);
    await panel(n+'ThighPocket',hip,[.11,-.085,side*.055],[.039,.105,.09],M.panelGray,.011);
    const knee=createPivot(n+'Knee',[0,-.235,0],hip);
    cyl(n+'KneeBand',knee,[0,0,0],.132,.132,.063,M.accent);
    await soft(n+'KneePad',knee,[.123,.003,0],[.066,.12,.19],M.accent,.025);
    const shin=createPivot(n+'Ankle',[0,-.245,0],knee);
    await soft(n+'Shin',knee,[0,-.121,0],[.234,.244,.229],M.panel,.039);
    await soft(n+'Boot',shin,[.04,-.026,0],[.33,.155,.258],M.trim,.04);
    await soft(n+'BootUpper',shin,[.008,.025,0],[.265,.13,.253],M.panel,.035);
    await soft(n+'ToeCap',shin,[.154,-.019,0],[.115,.113,.246],M.panelGray,.032);
    await panel(n+'Sole',shin,[.046,-.080,0],[.345,.05,.27],M.trim,.012);
  }
  root.scale.setScalar(1.8/1.64);
  defineBudget({triangles:BUDGETS.character},root);
  return root;
}
function animate() {
  const track=(name,values)=>rotationTrack('Joint_'+name,values.map(([time,rotation])=>({time,rotation})),'EASE_IN_OUT');
  const idle=createClip('Idle',4,[track('Spine',[[0,[0,0,0]],[2,[0,0,1]],[4,[0,0,0]]]),track('Head',[[0,[0,0,0]],[2,[0,2,0]],[4,[0,0,0]]])],{loop:true});
  const walkTracks=[];
  for(const side of [-1,1]){const n=side===1?'Right':'Left';
    walkTracks.push(track(n+'Hip',[[0,[0,0,-side*20]],[.5,[0,0,side*20]],[1,[0,0,-side*20]]]));
    walkTracks.push(track(n+'Knee',[[0,[0,0,side>0?25:0]],[.25,[0,0,side>0?0:30]],[.5,[0,0,side>0?0:25]],[.75,[0,0,side>0?30:0]],[1,[0,0,side>0?25:0]]]));
    walkTracks.push(track(n+'Shoulder',[[0,[-side*12,0,side*15]],[.5,[-side*12,0,-side*15]],[1,[-side*12,0,side*15]]]));
  }
  const walk=createClip('Walk',1,walkTracks,{loop:true});
  return [idle,walk,createClip('Friendly_Wave',8,[
    track('RightShoulder',[[0,[-12,0,0]],[1,[-12,0,0]],[2,[-123,0,0]],[5,[-123,0,0]],[6,[-12,0,0]],[8,[-12,0,0]]]),
    track('RightElbow',[[0,[0,0,0]],[2,[-23,0,-12]],[2.6,[10,0,-12]],[3.2,[-23,0,-12]],[3.8,[10,0,-12]],[4.4,[-23,0,-12]],[5,[10,0,-12]],[6,[0,0,0]],[8,[0,0,0]]]),
    track('Head',[[0,[0,0,0]],[2,[0,0,-5]],[5,[0,0,-5]],[6,[0,0,0]],[8,[0,0,0]]])
  ],{loop:true})];
}
